import {categories,templates,metrics,evaluate,valueFor,condition,fmt} from './domain.js';
import {chart} from './charts.js';
const $=s=>document.querySelector(s),el=(tag,value,cls)=>{const e=document.createElement(tag);if(value!==undefined)e.textContent=value;if(cls)e.className=cls;return e;};
let state={projects:[],blocks:[],specs:[],runs:[]},projectId=null,blockId=null,token,inspection=null,edits={},category=null,selectedDevice=null,wave=null,opSelection=null,schematic=null;
async function api(path,data){if(data!==undefined&&!token)token=(await (await fetch('/api/session')).json()).token;const response=await fetch('/api/'+path,data===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json','X-Workbench-Token':token},body:JSON.stringify(data)});const result=await response.json();if(!response.ok)throw Error(result.error||'요청 실패');return result;}
const notice=s=>$('#notice').textContent=s;
const block=()=>state.blocks.find(b=>b.id===blockId),runs=()=>state.runs.filter(r=>r.block_id===blockId),activeOp=()=>runs().find(r=>r.id===opSelection);
const stamp=r=>new Date(r.created*1000).toLocaleString('ko-KR');
const badge=(label,cls)=>el('span',label,'badge '+(cls||''));
function table(host,heads,rows){const t=el('table'),head=el('tr');heads.forEach(h=>head.append(el('th',h)));t.append(head);rows.forEach(values=>{const tr=el('tr');values.forEach(v=>{const td=el('td');td.append(v instanceof Node?v:document.createTextNode(String(v)));tr.append(td);});t.append(tr);});host.replaceChildren(t);}
function selectOptions(select,options,selected){select.replaceChildren();for(const [value,label]of options){const o=el('option',label);o.value=value;select.append(o);}if(options.some(o=>o[0]===selected))select.value=selected;}
function scopeText(r){const c=condition(r);return `${c.recipe==='dc'?'DC':'저장 분석'} · ${c.temperature??'—'} °C · ${c.corner||'corner 미기록'}`;}
function changeBlock(id){blockId=id;inspection=null;edits={};opSelection=null;selectedDevice=null;schematic=null;wave=null;$('#schematicView').replaceChildren();$('#deviceDetail').hidden=true;$('#testbenchInfo').textContent='테스트벤치를 연결해 저장된 설정을 확인하세요.';renderParameters();render();}
async function refresh(){state=await api('state');if(!state.projects.some(p=>p.id===projectId))projectId=state.projects[0]?.id;if(!state.blocks.some(b=>b.id===blockId&&b.project_id===projectId))blockId=(state.blocks.find(b=>b.project_id===projectId&&b.kind==='ota')||state.blocks.find(b=>b.project_id===projectId))?.id;render();$('#lastUpdated').textContent=new Date().toLocaleTimeString();}
function render(){
 const b=block();selectOptions($('#projectSelect'),state.projects.map(p=>[p.id,p.name]),projectId);$('#blockList').replaceChildren();for(const item of state.blocks.filter(b=>b.project_id===projectId)){const button=el('button',item.name,'block-button'+(item.id===blockId?' active':''));button.append(el('small',templates[item.kind]||item.kind));button.onclick=()=>changeBlock(item.id);$('#blockList').append(button);}
 $('#blockTitle').textContent=b?.name||'블록을 등록하세요';$('#blockSubtitle').textContent=b?`${templates[b.kind]} · ${b.cell} / schematic`:'프로젝트 안에 여러 블록과 테스트벤치를 연결할 수 있습니다.';$('#breadcrumb').textContent=(state.projects.find(p=>p.id===projectId)?.name||'PROJECT')+' / '+(b?.name||'BLOCK');
 for(const id of ['inspect','editBlock','addSpec','importRuns','schematic'])$('#'+id).disabled=!b;
 const items=specItems(),evals=b?items.filter(s=>s.id).map(s=>evaluate(s,runs(),b)):[],op=runs().find(r=>r.result?.operating_point),pending=runs().filter(r=>['queued','running'].includes(r.status));const powers=b?runs().map(r=>valueFor({metric:'power.dc',unit:'W',scope:{}},r,b)).filter(Number.isFinite):[];
 $('#summary').replaceChildren();for(const [name,value,note]of [['정의한 스펙',String(evals.length),'12개 측정 모듈'],['목표 대비',`${evals.filter(e=>e.status==='pass').length} / ${evals.length}`,'측정 범위 만족 / 정의'],['동작점 소자',String(op?.result.operating_point.devices.length||0),op?.result.operating_point.kind==='dc'?'DC 전용 실행':'DC / 시점 OP 구분'],['실행 중',String(pending.length),powers.length?'DC 전력 '+fmt(powers[0]*1e6)+' µW':'전원 매핑 후 전력 계산']]){const card=el('div',undefined,'summary-card');card.append(el('span',name),el('strong',value),el('small',note));$('#summary').append(card);}
 renderSpecs();renderOp();renderRuns();renderCompare();$('#run').disabled=!inspection;$('#sweep').disabled=!inspection;
}
function specItems(){const saved=state.specs.filter(s=>s.block_id===blockId);return [...saved,...Object.entries(metrics).filter(([key])=>!saved.some(s=>s.metric===key)).map(([metric,m])=>({...m,metric,target:null,comparison:m.direction,scope:{}}))];}
function renderSpecs(){
 $('#categoryGrid').replaceChildren();for(const [id,name,hint]of categories){const b=el('button');b.classList.toggle('active',category===id);b.append(el('small',id.padStart(2,'0')+' / '+hint),el('span',name));b.onclick=()=>{category=category===id?null:id;renderSpecs();};$('#categoryGrid').append(b);}
 $('#specRows').replaceChildren();for(const spec of specItems().filter(s=>!category||s.category===category)){const b=block(),v=b?evaluate(spec,runs(),b):{label:'미측정',status:'unmeasured'},row=el('tr'),name=el('td',spec.name);name.append(el('small',categories.find(c=>c[0]===spec.category)?.[1]||''));const conditionCell=el('td',v.worst?scopeText(v.worst.run):metrics[spec.metric]?.hint||'측정 레시피 연결 필요');conditionCell.append(el('small',v.worst?'근거 '+v.worst.run.result.job.slice(0,8):'—'));
  row.append(name,el('td',spec.target===null?'목표 미설정':`${spec.comparison==='min'?'≥':'≤'} ${fmt(spec.target)} ${spec.unit}`),el('td',v.worst?fmt(v.worst.value)+' '+spec.unit:'—'),el('td',Number.isFinite(v.margin)?fmt(v.margin)+' '+spec.unit:'—'),conditionCell,el('td'));row.lastChild.append(badge(v.label,v.status));row.style.cursor='pointer';row.onclick=()=>{const d=$('#metricDetail');d.hidden=false;d.replaceChildren(el('h3',spec.name),el('p',metrics[spec.metric]?.hint||'사용자 정의 지표입니다.'),el('p','판정 범위: '+JSON.stringify(spec.scope||{})+' · 최신 원본 회로의 실행만 비교합니다.'));const button=el('button','목표 · 조건 편집');button.onclick=()=>specForm(spec);d.append(button);};$('#specRows').append(row);
 }
}
function renderOp(){const opRuns=runs().filter(r=>r.result?.operating_point&&r.status==='completed');if(!opRuns.some(r=>r.id===opSelection))opSelection=opRuns[0]?.id;selectOptions($('#opRun'),opRuns.map(r=>[r.id,`${stamp(r)} · ${r.result.operating_point.kind==='dc'?'DC':'과도 종료 시점'} · ${condition(r).temperature??'—'} °C`]),opSelection);const r=activeOp(),op=r?.result.operating_point;$('#deviceRows').replaceChildren();
 if(!op){$('#opContext').textContent='동작점 데이터가 없습니다. 테스트벤치를 연결하고 DC 레시피로 실행하세요.';$('#marginChart').textContent='아직 데이터가 없습니다.';$('#gmChart').textContent='아직 데이터가 없습니다.';$('#powerTable').replaceChildren();return;}
 $('#opContext').textContent=`${op.kind==='dc'?'DC 전용 동작점':'과도해석 종료 시점의 동작점'} · ${scopeText(r)} · 마진은 |VDS|−|VDSAT| 진단값. region은 PDK 원본 코드이며 모든 소자에 포화를 요구하지 않습니다.`;
 const devices=op.devices;for(const d of devices){const row=el('tr');row.dataset.device=d.name;row.classList.toggle('selected',d.name===selectedDevice);const role=el('select');role.setAttribute('aria-label',d.name+' 의도');selectOptions(role,[['observe','관찰'],['saturation','포화 의도'],['switch','스위치'],['off','꺼짐 의도']],block().roles[d.name]||'observe');role.onclick=e=>e.stopPropagation();role.onchange=async()=>{const b=block();try{await api('block',{...b,roles:{...b.roles,[d.name]:role.value}});await refresh();}catch(e){notice(e.message);}};const roleCell=el('td');roleCell.append(role);row.append(el('td',d.name),roleCell,...[d.id*1e6,d.gm*1e6,d.gm_id,d.vds,d.vdsat,d.margin*1000,d.region].map(x=>el('td',fmt(x),'numeric')));row.onclick=()=>showDevice(d);$('#deviceRows').append(row);}
 chart($('#marginChart'),[{name:'마진 (소자 인덱스)',points:devices.map((d,i)=>[i+1,d.margin*1000])}],{xLabel:'소자 순서 · 표와 동일',yLabel:'마진 [mV]',horizontal:[{value:0}]});
 chart($('#gmChart'),[{name:'gm/ID',points:devices.filter(d=>Number.isFinite(d.gm_id)&&Math.abs(d.id)>1e-15).map(d=>[Math.abs(d.id)*1e6,d.gm_id]).sort((a,b)=>a[0]-b[0])}],{xLabel:'|ID| [µA]',yLabel:'gm/ID [1/V]',logX:true});
 table($('#powerTable'),['전압원','선택','전압 [V]','전류 [µA]','공급 전력 [µW]'],op.sources.map(s=>[s.name,block().rails.includes(s.name)?'전력 합산':'미선택',fmt(s.raw.v),fmt(s.raw.i*1e6),fmt(-s.raw.pwr*1e6)]));
 if(op.kind!=='dc')$('#powerTable').append(el('p','위 값은 과도 종료 시점의 순간값이며 평균 소비전력이 아닙니다.','help-note'));
}
function showDevice(d){selectedDevice=d.name;$('#deviceDetail').hidden=false;$('#deviceDetail').replaceChildren(el('h3',d.name+' · '+d.model),el('p','원본 OP 데이터 · '+(activeOp()?.result.operating_point.kind==='dc'?'DC':'과도 종료 시점')),el('pre',JSON.stringify(d.raw,null,2)));$('#deviceRows').querySelectorAll('tr').forEach(row=>row.style.background=row.dataset.device===d.name?'#243c5c':'');$('#schematicView').querySelectorAll('button').forEach(b=>b.classList.toggle('selected',b.dataset.name===d.name));}
function renderCompare(){const valid=runs().filter(r=>r.status==='completed'&&r.result?.operating_point);table($('#conditionTable'),['실행','원본 버전','조건','변경값','근거'],valid.map(r=>[stamp(r),r.result.source_sha256.slice(0,10),scopeText(r),JSON.stringify(r.payload.overrides),r.result.operating_point.kind]));const source=valid[0]?.result.source_sha256;
 const pairs=valid.filter(r=>r.result.source_sha256===source&&r.result.operating_point.kind==='dc');const reference=pairs[0];const signature=r=>JSON.stringify(Object.entries(r.payload.overrides||{}).filter(([k])=>k!=='simulatorOptions.temp').sort());const matched=reference?pairs.filter(r=>signature(r)===signature(reference)):[];
 const plotMetric=(id,metric,unit,factor)=>{const points=matched.map(r=>[condition(r).temperature,valueFor({metric,unit,scope:{}},r,block())]).filter(p=>p.every(Number.isFinite)).map(([x,y])=>[x,y*factor]).sort((a,b)=>a[0]-b[0]);if(points.length<2)$('#'+id).textContent='온도 외 조건이 같은 DC 결과가 2개 이상 필요합니다.';else chart($('#'+id),[{name:metric,points}],{xLabel:'온도 [°C]',yLabel:unit==='W'?'전력 [µW]':'마진 [mV]'});};if(block()){plotMetric('powerChart','power.dc','W',1e6);plotMetric('conditionMarginChart','op.margin.min','V',1000);}
 const old=$('#waveRun').value;selectOptions($('#waveRun'),runs().filter(r=>r.result?.measurements).map(r=>[r.id,stamp(r)+' · '+r.result.cell]),old);
}
function renderRuns(){const list=$('#runList');list.replaceChildren();if(!runs().length)list.append(el('div','아직 실행 기록이 없습니다.','empty'));for(const r of runs()){const card=el('article',undefined,'run-card'),head=el('div',undefined,'run-title');head.append(el('strong',`${r.payload.recipe==='dc'?'DC 동작점':'저장 분석'} · ${stamp(r)}`),badge(({queued:'대기',running:'실행 중',completed:'실행 완료',failed:'실행 실패',cancelled:'취소',interrupted:'중단됨'})[r.status]||r.status,r.status==='failed'?'fail':''));card.append(head,el('p',JSON.stringify(r.payload.overrides)));if(r.error)card.append(el('p',r.error));if(r.result?.operating_point_error)card.append(el('p','동작점 읽기 실패: '+r.result.operating_point_error));if(r.result?.measurement_error)card.append(el('p','파형 측정 실패: '+r.result.measurement_error));if(['queued','running'].includes(r.status)){const cancel=el('button',r.status==='queued'?'예약 취소':'진행 중 · 최대 60초');cancel.disabled=r.status==='running';cancel.onclick=async()=>{try{await api('cancel',{id:r.id});notice('중지 요청을 기록했습니다. 이미 시작한 시뮬레이션 결과는 보존됩니다.');await refresh();}catch(e){notice(e.message);}};card.append(cancel);}if(r.result){const details=el('details');details.append(el('summary','실행 조건 · 원본 로그'),el('pre',JSON.stringify({job:r.result.job,source:r.result.source_sha256,executed:r.result.executed_sha256,kind:r.result.operating_point?.kind},null,2)+'\n'+r.result.log_tail));card.append(details);}list.append(card);}}
function renderParameters(){const host=$('#parameters');host.replaceChildren();const query=$('#parameterSearch').value.toLowerCase();for(const p of inspection?.parameters||[]){if(!p.key.toLowerCase().includes(query))continue;const label=el('label',undefined,'parameter'),name=el('span',p.key);name.append(el('small','원본 '+p.value));const input=el('input');input.value=edits[p.key]??p.value;input.setAttribute('aria-label',p.key);input.oninput=()=>{if(input.value===p.value)delete edits[p.key];else edits[p.key]=input.value;};label.append(name,input);host.append(label);}}
function form(title,fields,submit){$('#dialogTitle').textContent=title;$('#dialogBody').replaceChildren();$('#formError').textContent='';const inputs={};for(const f of fields){const label=el('label',f.label),input=el(f.options?'select':'input');input.name=f.key;if(!f.options)input.type=f.type||'text';input.required=!!f.required;if(f.options)selectOptions(input,f.options,f.value);else input.value=f.value??'';if(f.type==='number')input.step='any';label.append(input);$('#dialogBody').append(label);inputs[f.key]=input;}$('#dialogForm').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{await submit(Object.fromEntries(Object.entries(inputs).map(([k,input])=>[k,input.value])));$('#dialog').close();await refresh();}catch(error){$('#formError').textContent=error.message;}finally{button.disabled=false;}};$('#dialog').showModal();return inputs;}
function blockForm(existing){form(existing?'블록 설정':'블록 등록',[{key:'name',label:'블록 이름',value:existing?.name,required:true},{key:'kind',label:'블록 템플릿',value:existing?.kind||'ota',options:Object.entries(templates)},{key:'cell',label:'저장된 ADE 테스트벤치 셀',value:existing?.cell,required:true},{key:'rails',label:'전력 합산 전압원 (쉼표 구분, 예: V6)',value:existing?.rails.join(',')||''}],async data=>{const r=await api('block',{...existing,...data,project_id:projectId,rails:data.rails.split(',').map(s=>s.trim()).filter(Boolean),roles:existing?.roles||{}});blockId=r.id;inspection=null;edits={};renderParameters();});}
function specForm(s){const metric=s?.metric||'power.dc',m=metrics[metric]||{};form('스펙 목표 · 측정 조건',[{key:'metric',label:'측정 지표',value:metric,options:Object.entries(metrics).map(([key,m])=>[key,m.name+' ['+m.unit+']'])},{key:'name',label:'스펙 이름',value:s?.name||m.name,required:true},{key:'comparison',label:'판정',value:s?.comparison||m.direction,options:[['min','최솟값 이상'],['max','최댓값 이하']]},{key:'target',label:'목표값 (지표에 표시된 SI 단위, 비우면 미설정)',type:'number',value:s?.target??''},{key:'recipe',label:'분석 범위',value:s?.scope?.recipe||'dc',options:[['dc','DC'],['saved','저장 분석'],['','모든 분석']]},{key:'temperature',label:'온도 조건 [°C] (비우면 모든 측정 온도)',type:'number',value:s?.scope?.temperature??''},{key:'corner',label:'PDK corner 이름 (비우면 모든 측정 corner)',value:s?.scope?.corner||''}],async data=>{const def=metrics[data.metric],scope={};if(data.recipe)scope.recipe=data.recipe;if(data.temperature!=='')scope.temperature=Number(data.temperature);if(data.corner)scope.corner=data.corner;await api('spec',{id:s?.id,block_id:blockId,category:def.category,name:data.name,metric:data.metric,unit:def.unit,comparison:data.comparison,target:data.target===''?null:Number(data.target),scope});});}
$('#projectSelect').onchange=()=>{projectId=$('#projectSelect').value;changeBlock(state.blocks.find(b=>b.project_id===projectId)?.id);};$('#addProject').onclick=()=>form('프로젝트 만들기',[{key:'name',label:'프로젝트 이름',required:true}],async data=>{projectId=(await api('project',data)).id;blockId=null;});$('#addBlock').onclick=()=>blockForm();$('#editBlock').onclick=()=>blockForm(block());$('#addSpec').onclick=()=>specForm();$('#closeDialog').onclick=()=>$('#dialog').close();$('#refresh').onclick=()=>refresh().catch(e=>notice(e.message));
$('#inspect').onclick=async()=>{notice('저장된 테스트벤치를 확인하는 중…');$('#inspect').disabled=true;try{const id=blockId;const result=await api('inspect',{block_id:id});if(id!==blockId)return;inspection=result;block().inspection=result;edits={};$('#testbenchInfo').textContent=`${result.cell} · ${result.analyses.join(', ')} · 파라미터 ${result.parameters.length}개 · 원본 ${result.sha256.slice(0,12)}`;renderParameters();render();notice('테스트벤치 연결 완료. 실행 탭에서 DC 또는 저장된 분석을 예약할 수 있습니다.');}catch(e){notice('연결 실패: '+e.message);}finally{$('#inspect').disabled=!block();}};
async function queue(candidates){if(!inspection)return;const b=blockId,hash=inspection.sha256,recipe=$('#recipe').value;try{for(const overrides of candidates)await api('run',{block_id:b,expected_sha256:hash,overrides,recipe});notice(candidates.length+'개 실행을 예약했습니다. 새로고침해도 기록이 유지됩니다.');await refresh();}catch(e){notice(e.message);}}
$('#run').onclick=()=>queue([{...edits}]);$('#sweep').onclick=()=>{const keys=$('#sweepKeys').value.split(',').map(s=>s.trim()).filter(Boolean),values=$('#sweepValues').value.split(',').map(s=>s.trim()).filter(Boolean);if(!keys.length||!values.length||values.length>12||keys.some(k=>!inspection.parameters.some(p=>p.key===k)))return notice('파라미터 목록의 키와 최대 12개 값을 입력하세요.');queue(values.map(value=>({...edits,...Object.fromEntries(keys.map(key=>[key,value]))})));};$('#parameterSearch').oninput=renderParameters;
$('#importRuns').onclick=async()=>{try{const list=(await api('available-runs')).runs.filter(r=>r.cell===block().cell);if(!list.length)return notice('이 테스트벤치의 기존 결과가 없습니다.');form('기존 결과 연결',[{key:'job',label:'실행 선택',options:list.map(r=>[r.job,`${r.recipe} · ${r.has_op?'OP 있음':'파형'} · ${r.job.slice(0,10)}`])}],data=>api('import',{block_id:blockId,job:data.job}));}catch(e){notice(e.message);}};
$('#opRun').onchange=()=>{opSelection=$('#opRun').value;renderOp();};
$('#schematic').onclick=async()=>{try{notice('현재 Cadence 셀 연결을 읽는 중…');const result=await api('schematic',{}),top=result.circuit.cells.find(c=>c.id===result.circuit.top);if(top.name!==block().cell)throw Error('현재 Cadence 셀 '+top.name+'은 선택한 테스트벤치와 다릅니다.');schematic=top;$('#schematicView').replaceChildren();for(const inst of top.instances){const b=el('button',inst.name,'device-chip');b.dataset.name=inst.name;b.append(el('small',inst.cell));b.onclick=()=>{const d=activeOp()?.result.operating_point.devices.find(d=>d.name===inst.name);if(d)showDevice(d);else{$('#deviceDetail').hidden=false;$('#deviceDetail').replaceChildren(el('h3',inst.name),el('p','선택한 실행에 이 소자의 OP가 없습니다.'));}$('#deviceDetail').append(el('pre',inst.pins.map(p=>p.name+' → '+(p.net??'미연결')).join('\n')));};$('#schematicView').append(b);}notice('현재 셀의 소자·핀 연결을 읽었습니다. 실행 당시 회로와의 동일성은 별도 확인이 필요합니다.');}catch(e){notice(e.message);}};
$('#loadWave').onclick=async()=>{const id=$('#waveRun').value;if(!id)return notice('과도해석 파형이 있는 실행을 선택하세요.');try{notice('파형을 읽는 중…');const result=await api('waveform',{id});const lines=result.csv.trim().split(/\r?\n/),headers=lines.shift().split(','),rows=lines.map(l=>l.split(',').map(Number));if(headers.some(h=>h.includes('"'))||rows.some(r=>r.length!==headers.length||!r.every(Number.isFinite)))throw Error('지원되지 않는 CSV 형식');wave={id,headers,rows};selectOptions($('#waveSignal'),headers.slice(1).map(h=>[h,h]),headers.find(h=>h==='Vop_V'));$('#waveStart').value=rows[0][0]*1000;$('#waveEnd').value=rows.at(-1)[0]*1000;drawWave();notice('원본 파형 '+rows.length+'개 샘플을 읽었습니다.');}catch(e){notice(e.message);}};
function drawWave(){if(!wave)return;const start=Number($('#waveStart').value)/1000,end=Number($('#waveEnd').value)/1000,index=wave.headers.indexOf($('#waveSignal').value),rows=wave.rows.filter(r=>r[0]>=start&&r[0]<=end);if(rows.length<2||index<1)return notice('유효한 신호와 시간 구간을 입력하세요.');const points=[],width=Math.max(1,Math.ceil(rows.length/1500));for(let i=0;i<rows.length;i+=width){const group=rows.slice(i,i+width);let min=group[0],max=group[0];for(const r of group){if(r[index]<min[index])min=r;if(r[index]>max[index])max=r;}points.push(...[min,max].sort((a,b)=>a[0]-b[0]).map(r=>[r[0]*1000,r[index]]));}chart($('#waveChart'),[{name:wave.headers[index],points}],{xLabel:'시간 [ms]',yLabel:wave.headers[index].endsWith('_A')?'A':'V'});}
$('#drawWave').onclick=drawWave;$('#waveSignal').onchange=drawWave;
$('#export').onclick=()=>{const data={schema:'circuit-workbench-project/1',project:state.projects.find(p=>p.id===projectId),blocks:state.blocks.filter(b=>b.project_id===projectId)};const ids=data.blocks.map(b=>b.id);data.specs=state.specs.filter(s=>ids.includes(s.block_id));data.runs=state.runs.filter(r=>ids.includes(r.block_id));const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=el('a');a.href=url;a.download='circuit-workbench-project.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('[data-tab="overview"]').classList.add('active');document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.tab-panel').forEach(p=>p.hidden=p.id!==b.dataset.tab);});
refresh().then(()=>notice('프로젝트를 불러왔습니다. 실제 측정과 목표를 연결해 보세요.')).catch(e=>notice('연결 실패: '+e.message));
setInterval(()=>{if(state.runs.some(r=>['queued','running'].includes(r.status)))refresh().catch(e=>notice(e.message));},2000);
